#include "geometry_deformation_worker_pool.h"
#include <fstream>
#include <iostream>
#include <chrono>
std::vector<uint8_t>read(const char*p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("fixture missing");return {(std::istreambuf_iterator<char>(f)),{}};}
bool equal(const GeometryDeformedVertexCandidate&a,const GeometryDeformedVertexCandidate&b){return !std::memcmp(a.position.data(),b.position.data(),12)&&!std::memcmp(a.normal.data(),b.normal.data(),12)&&!std::memcmp(a.uv.data(),b.uv.data(),8)&&!std::memcmp(a.tangent.data(),b.tangent.data(),16)&&a.hasTangent==b.hasTangent;}
int main(int argc,char**argv){try{
 static_assert(sizeof(void*)==8,"x64 required");if(argc!=3)throw std::runtime_error("MDL VVD required");auto mdl=read(argv[1]),vvd=read(argv[2]);auto bones=readGeometrySkeletonCandidate(mdl);uint32_t checksum;std::memcpy(&checksum,mdl.data()+8,4);auto geometry=readVvdGeometryCandidate(vvd,checksum,0);auto saved=geometry;std::vector<GeometryMatrixCandidate>locals;for(auto&b:bones)locals.push_back(b.local);for(size_t n=0;n<bones.size();++n)if(bones[n].parent<0)locals[n][3]+=10;auto palette=evaluateGeometryPosePaletteCandidate(bones,locals);auto reference=deformGeometryBatchCandidate(geometry,palette,0);
 for(size_t n=0;n<reference.size();++n){const auto&vertex=geometry.vertices[n];std::array<float,3>normal;std::memcpy(normal.data(),vertex.data()+28,12);auto expected=skinGeometryDirectionCandidate(vertex,normal,palette);if(std::memcmp(expected.data(),reference[n].normal.data(),12))throw std::runtime_error("validated normal reuse changed bits");if(!geometry.tangents.empty()){std::array<float,4>tangent;std::memcpy(tangent.data(),geometry.tangents[n].data(),16);auto direction=skinGeometryDirectionCandidate(vertex,{tangent[0],tangent[1],tangent[2]},palette);if(std::memcmp(direction.data(),reference[n].tangent.data(),12)||std::memcmp(&tangent[3],&reference[n].tangent[3],4))throw std::runtime_error("validated tangent reuse changed bits");}}
 for(size_t workers:{size_t(1),size_t(2),size_t(4),size_t(8)}){GeometryDeformationWorkerPoolCandidate pool(workers);auto start=std::chrono::steady_clock::now();for(int iteration=0;iteration<4;++iteration){auto result=pool.deform(geometry,palette);if(result.size()!=reference.size())throw std::runtime_error("output count");for(size_t n=0;n<result.size();++n)if(!equal(result[n],reference[n]))throw std::runtime_error("parallel output mismatch");}auto ms=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();std::cout<<"workers="<<workers<<" four_batches_ms="<<ms<<'\n';}
 if(geometry.vertices!=saved.vertices||geometry.tangents!=saved.tangents)throw std::runtime_error("input mutated");unsigned rejected=0;for(size_t workers:{size_t(0),size_t(2),size_t(8)}){auto bad=geometry;bad.vertices[0][15]=4;bad.vertices[1][12]=255;bool failed=false;try{GeometryDeformationWorkerPoolCandidate pool(workers?workers:1);pool.deform(bad,palette);auto recovered=pool.deform(geometry,palette);if(recovered.size()!=reference.size())throw std::runtime_error("recovery count");}catch(const std::runtime_error&e){if(std::string(e.what())!="skin influence count")throw;failed=true;}if(!failed)throw std::runtime_error("malformed batch accepted");GeometryDeformationWorkerPoolCandidate recovery(workers?workers:1);try{recovery.deform(bad,palette);}catch(const std::runtime_error&){}auto good=recovery.deform(geometry,palette);for(size_t n=0;n<good.size();++n)if(!equal(good[n],reference[n]))throw std::runtime_error("pool recovery mismatch");++rejected;}
 for(int scenario=0;scenario<2;++scenario){auto bad=geometry;if(scenario==0)bad.tangents.pop_back();bool failed=false;try{deformGeometryBatchCandidate(bad,palette,scenario==0?4:65);}catch(const std::runtime_error&){failed=true;}if(!failed)throw std::runtime_error("invalid batch accepted");++rejected;}
 if(!deformGeometryBatchCandidate({},palette,8).empty())throw std::runtime_error("empty batch");std::cout<<"x64 retained geometry pool byte-exact vertices="<<reference.size()<<" rejected="<<rejected<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
